select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"work_id":987109001,"language":"nl"},"seq":1,"relation":"catalog_work_descriptions","after_row":{"text":"Wanneer hun woongebied wordt bedreigd, trekt een groep wilde konijnen weg om een veilige plek te zoeken. Buiten de vertrouwde omgeving krijgen ze te maken met roofdieren, mensen en andere konijnengemeenschappen. Onderweg blijkt overleven niet alleen een kwestie van snelheid of kracht: de dieren moeten ook samenwerken en beslissen wie zij vertrouwen. Richard Adams vertelt hun tocht vanuit een eigen konijnenwereld, met gebruiken en verhalen die betekenis geven aan gevaar, leiderschap en een nieuw thuis.","work_id":987109001,"evidence":[{"note":"Same WatershipDown novel by RichardGeorgeAdams. Duplicate source-author names are not separate coauthors or a reason to merge catalogue authors. Existing Work and primary author retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p80253645X","http://data.bibliotheken.nl/id/nbt/p801818451","http://data.bibliotheken.nl/id/nbt/p854168001","http://data.bibliotheken.nl/id/nbt/p802630111"],"reference":"work:1464","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL2096536W","https://data.bibliotheken.nl/id/nbt/p80253645X","https://data.bibliotheken.nl/id/nbt/p801818451","https://data.bibliotheken.nl/id/nbt/p854168001","https://data.bibliotheken.nl/id/nbt/p802630111"]},{"type":"cover_front_review","sha256":"626babc362f2f2ee5304dba394a2a8997f566924e23c195d12eb4341a49bcf7a","cover_id":6781577,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-002.jpg. Richard Adams; Waterschapsheuvel. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL2096536W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309002},"before_row":null},{"key":{"edition_id":987209001},"seq":2,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987109001,"evidence":[{"note":"Same WatershipDown novel by RichardGeorgeAdams. Duplicate source-author names are not separate coauthors or a reason to merge catalogue authors. Existing Work and primary author retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p80253645X","http://data.bibliotheken.nl/id/nbt/p801818451","http://data.bibliotheken.nl/id/nbt/p854168001","http://data.bibliotheken.nl/id/nbt/p802630111"],"reference":"work:1464","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL2096536W","https://data.bibliotheken.nl/id/nbt/p80253645X","https://data.bibliotheken.nl/id/nbt/p801818451","https://data.bibliotheken.nl/id/nbt/p854168001","https://data.bibliotheken.nl/id/nbt/p802630111"]},{"type":"cover_front_review","sha256":"626babc362f2f2ee5304dba394a2a8997f566924e23c195d12eb4341a49bcf7a","cover_id":6781577,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-002.jpg. Richard Adams; Waterschapsheuvel. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6781577-L.jpg?default=false","edition_id":987209001,"bound_title":"Waterschapsheuvel","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789027408112","evidence_url":"https://data.bibliotheken.nl/id/nbt/p80253645X","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/6781577-M.jpg?default=false","bound_author_id":987309002},"before_row":null},{"key":{"work_id":987109005,"language":"nl"},"seq":3,"relation":"catalog_work_descriptions","after_row":{"text":"De vijftienjarige Michael Berg leert Hanna kennen wanneer zij hem helpt. Tussen hen ontstaat een geheime verhouding, maar over haar achtergrond laat zij weinig los. Op een dag verdwijnt ze uit zijn leven. Jaren later ziet Michael haar als rechtenstudent terug in een rechtszaal. Hij moet zijn herinneringen aan haar dan verbinden met wat daar over haar verleden aan het licht komt. De roman onderzoekt hoe persoonlijke verbondenheid, schuld en de Duitse geschiedenis elkaar kunnen doorkruisen.","work_id":987109005,"evidence":[{"note":"Exact Dutch translation of Schlink’s DerVorleser1995, not a movie edition or unrelated reader anthology.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p183640144"],"reference":"work:3332","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL14871157W","https://data.bibliotheken.nl/id/nbt/p183640144"]},{"type":"cover_front_review","sha256":"795ce20cea3127ba4d6ddd199a683c6c4ad70fc245342fd7cc376fb53e8970af","cover_id":13197724,"reference":"cover-semantic-review-003.json","limitation":"Title and Bernhard Schlink readable;129×212 original supports small card only, no sharp detail assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL14871157W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309006},"before_row":null},{"key":{"edition_id":987209007},"seq":4,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987109005,"evidence":[{"note":"Exact Dutch translation of Schlink’s DerVorleser1995, not a movie edition or unrelated reader anthology.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p183640144"],"reference":"work:3332","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-021.json","sources":["https://openlibrary.org/works/OL14871157W","https://data.bibliotheken.nl/id/nbt/p183640144"]},{"type":"cover_front_review","sha256":"795ce20cea3127ba4d6ddd199a683c6c4ad70fc245342fd7cc376fb53e8970af","cover_id":13197724,"reference":"cover-semantic-review-003.json","limitation":"Title and Bernhard Schlink readable;129×212 original supports small card only, no sharp detail assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13197724-L.jpg?default=false","edition_id":987209007,"bound_title":"De voorlezer","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789041403704","evidence_url":"https://data.bibliotheken.nl/id/nbt/p183640144","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13197724-M.jpg?default=false","bound_author_id":987309006},"before_row":null},{"key":{"work_id":987109002,"language":"nl"},"seq":5,"relation":"catalog_work_descriptions","after_row":{"text":"Richard Dawkins verzamelt in dit boek verschillende soorten bewijs voor evolutie. Hij bespreekt waarneembare natuurlijke selectie, het fossielenbestand en overeenkomsten die met genetisch onderzoek zichtbaar worden. Ook legt hij uit hoe de ouderdom van materiaal kan worden bepaald. De voorbeelden komen uit uiteenlopende wetenschappelijke vakgebieden en worden verbonden met zijn kritiek op creationistische verklaringen. Het doel is niet alleen Darwins gedachtegang te beschrijven, maar te laten zien op welke onderzoeksresultaten de moderne evolutionaire verklaring steunt.","work_id":987109002,"evidence":[{"note":"Dawkins science non-fiction TheGreatestShowonEarth2009; exact NieuwAmsterdam paperback. No automatic taste traits or claims of measured popularity.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p320421872"],"reference":"work:2409","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://openlibrary.org/works/OL1966487W","https://data.bibliotheken.nl/id/nbt/p320421872"]},{"type":"cover_front_review","sha256":"1b64d82da3e00bb1c4a3c79e0605c464cb4b8ac584ea5008f77adce8ee2edcbd","cover_id":6832257,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Richard Dawkins; Het grootste spektakel ter wereld; Bewijs voor evolutie; Nieuw Amsterdam. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL1966487W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309001},"before_row":null},{"key":{"edition_id":987209003},"seq":6,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987109002,"evidence":[{"note":"Dawkins science non-fiction TheGreatestShowonEarth2009; exact NieuwAmsterdam paperback. No automatic taste traits or claims of measured popularity.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p320421872"],"reference":"work:2409","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-022.json","sources":["https://openlibrary.org/works/OL1966487W","https://data.bibliotheken.nl/id/nbt/p320421872"]},{"type":"cover_front_review","sha256":"1b64d82da3e00bb1c4a3c79e0605c464cb4b8ac584ea5008f77adce8ee2edcbd","cover_id":6832257,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Richard Dawkins; Het grootste spektakel ter wereld; Bewijs voor evolutie; Nieuw Amsterdam. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6832257-L.jpg?default=false","edition_id":987209003,"bound_title":"Het grootste spektakel ter wereld","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789046806517","evidence_url":"https://data.bibliotheken.nl/id/nbt/p320421872","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/6832257-M.jpg?default=false","bound_author_id":987309001},"before_row":null},{"key":{"work_id":987109007,"language":"nl"},"seq":7,"relation":"catalog_work_descriptions","after_row":{"text":"Saúl Zuratas verlaat de wereld van zijn universitaire studie en wordt verteller bij de Machiguenga in Peru. Zijn keuze vormt een aanleiding om verschillende manieren van leven en verhalen doorgeven naast elkaar te plaatsen. De roman onderzoekt ook de invloed van westerse missies en antropologisch onderzoek op inheemse gemeenschappen. Vargas Llosa stelt vragen bij de verwachting dat zo''n cultuur onveranderd zou moeten blijven. Het vertellen zelf wordt een manier om te onderzoeken hoe verbondenheid en verandering met elkaar kunnen samengaan.","work_id":987109007,"evidence":[{"note":"VargasLlosa Elhablador1987. One Dutch paperback and original source identity, retain Work5055.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p051592827"],"reference":"work:5055","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-028.json","sources":["https://openlibrary.org/works/OL857555W","https://data.bibliotheken.nl/id/nbt/p051592827"]},{"type":"cover_front_review","sha256":"900708ea4b57ddc3468d07921d9b22da2020627afcae0e6d5bc88e3eb0412bb3","cover_id":12552996,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL857555W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987304007},"before_row":null},{"key":{"edition_id":987209009},"seq":8,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987109007,"evidence":[{"note":"VargasLlosa Elhablador1987. One Dutch paperback and original source identity, retain Work5055.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p051592827"],"reference":"work:5055","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-028.json","sources":["https://openlibrary.org/works/OL857555W","https://data.bibliotheken.nl/id/nbt/p051592827"]},{"type":"cover_front_review","sha256":"900708ea4b57ddc3468d07921d9b22da2020627afcae0e6d5bc88e3eb0412bb3","cover_id":12552996,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/12552996-L.jpg?default=false","edition_id":987209009,"bound_title":"Het woord van de verteller","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789029039116","evidence_url":"https://data.bibliotheken.nl/id/nbt/p051592827","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/12552996-M.jpg?default=false","bound_author_id":987304007},"before_row":null},{"key":{"work_id":987109006,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"In 2120 ligt Londen in puin. Prins Alfred kent alleen het leven binnen Buckingham Palace, maar ook daar dringt het gevaar binnen. ''s Nachts gebeuren er vreemde dingen in de gangen en de wereld buiten het paleis blijkt vol monsters en geheimen. Wanneer zijn moeder, de koningin, naar de Tower wordt weggevoerd, moet Alfred zijn beschutte bestaan verlaten. David Walliams laat de jonge prins zoeken naar de moed om te handelen in een stad waarvan hij de werkelijkheid nauwelijks heeft leren kennen.","work_id":987109006,"evidence":[{"note":"Walliams children’s novel, Clavis hardcover. Current content summary does not claim source2020citation as first original year.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p435573187"],"reference":"work:3535","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-029.json","sources":["https://openlibrary.org/works/OL20659782W","https://data.bibliotheken.nl/id/nbt/p435573187"]},{"type":"cover_front_review","sha256":"e05da75b509789000eab0f9059144851a8f604dd8b73eb1d62efbe57b6a3c62a","cover_id":13649954,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL20659782W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309003},"before_row":null},{"key":{"edition_id":987209008},"seq":10,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":987109006,"evidence":[{"note":"Walliams children’s novel, Clavis hardcover. Current content summary does not claim source2020citation as first original year.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p435573187"],"reference":"work:3535","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-029.json","sources":["https://openlibrary.org/works/OL20659782W","https://data.bibliotheken.nl/id/nbt/p435573187"]},{"type":"cover_front_review","sha256":"e05da75b509789000eab0f9059144851a8f604dd8b73eb1d62efbe57b6a3c62a","cover_id":13649954,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/13649954-L.jpg?default=false","edition_id":987209008,"bound_title":"Het beest van Buckingham Palace","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789044839142","evidence_url":"https://data.bibliotheken.nl/id/nbt/p435573187","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13649954-M.jpg?default=false","bound_author_id":987309003},"before_row":null},{"key":{"work_id":987109003,"language":"nl"},"seq":11,"relation":"catalog_work_descriptions","after_row":{"text":"Lotte komt naar Weimar in de verwachting Goethe na veertig jaar opnieuw te ontmoeten. In haar jeugd stond zij model voor de Charlotte uit zijn beroemde Werther. De voorbereiding op hun weerzien brengt herinneringen en verwachtingen naar boven. Door gesprekken met mensen uit Goethes omgeving ontstaat bovendien niet één vast beeld van de schrijver, maar een reeks verschillende perspectieven. Thomas Mann onderzoekt hoe een beroemd kunstwerk en de mensen die ermee verbonden zijn elkaar blijven beïnvloeden wanneer hun levens inmiddels ver uiteen zijn gegaan.","work_id":987109003,"evidence":[{"note":"ThomasMann LotteinWeimar1939 novel about Goethe; not a book authored by Goethe or a documentary biography.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p039865398"],"reference":"work:3179","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-031.json","sources":["https://openlibrary.org/works/OL14867077W","https://data.bibliotheken.nl/id/nbt/p039865398"]},{"type":"cover_front_review","sha256":"ac353b0d68960f506ab168cdc71d9ded84fa88635cbbcdd5d0ca9bd5bf60a6dd","cover_id":6878821,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Thomas Mann; Lotte in Weimar; De Arbeiderspers. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL14867077W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309005},"before_row":null},{"key":{"edition_id":987209005},"seq":12,"relation":"catalog_edition_metadata","after_row