Iris Murdoch onderzoekt hoe een terugkeer oude rollen kan activeren en hoe moeilijk het is werkelijk buiten een familiegeschiedenis te gaan staan.","work_id":987109004,"evidence":[{"note":"IrisMurdoch TheItalianGirl1964, exact Querido/Salamander paperback. No new identity from full-name authorityJeanIrisMurdoch.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801993296"],"reference":"work:3202","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-031.json","sources":["https://openlibrary.org/works/OL1326316W","https://data.bibliotheken.nl/id/nbt/p801993296"]},{"type":"cover_front_review","sha256":"07f770a2347e22734928aea5ab196fcf71a87a5dd56c5c1cf098c461b645e4eb","cover_id":6964827,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Iris Murdoch; Het Italiaanse meisje; Salamander. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL1326316W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309004},"before_row":null},{"key":{"edition_id":987209006},"seq":14,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987109004,"evidence":[{"note":"IrisMurdoch TheItalianGirl1964, exact Querido/Salamander paperback. No new identity from full-name authorityJeanIrisMurdoch.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p801993296"],"reference":"work:3202","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":