ography","sources":["http://data.bibliotheken.nl/id/nbt/p240311930"],"reference":"work:6012","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL3123542W","https://data.bibliotheken.nl/id/nbt/p240311930"]},{"type":"cover_front_review","sha256":"2741e5c8c02e90d02e6f4649d8d52014416badd54cfff1fd046c76dd8726d89e","cover_id":13262380,"reference":"cover-semantic-review-003.json","limitation":"1979/Christian Kracht readable but source low resolution; no high-detail quality claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL3123542W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309007},"before_row":null},{"key":{"edition_id":987209011},"seq":18,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":987109009,"evidence":[{"note":"ChristianKracht1979 is the novel title; original publication2001 remains separate. Exact Dutch hardcover.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p240311930"],"reference":"work:6012","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL3123542W","https://data.bibliotheken.nl/id/nbt/p240311930"]},{"type":"cover_front_review","sha256":"2741e5c8c02e90d02e6f4649d8d52014416badd54cfff1fd046c76dd8726d89e","cover_id":13262380,"reference":"cover-semantic-review-003.json","limitation":"1979/Christian Kracht readable but source low resolution; no high-detail quality claim."}],"cover_url":"https://covers.openlibrary.org/b/id/13262380-L.jpg?default=false","edition_id":987209011,"bound_title":"1979","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789029525466","evidence_url":"https://data.bibliotheken.nl/id/nbt/p240311930","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/13262380-M.jpg?default=false","bound_author_id":987309007},"before_row":null},{"key":{"work_id":987109010,"language":"nl"},"seq":19,"relation":"catalog_work_descriptions","after_row":{"text":"De kinderen mogen een nacht in de speelzaal van hun kleuterschool blijven. Met spoken, monsters en vampiers wordt er een verkleedfeest van gemaakt. Voor Luisa hoort bij zo''n avond ook de vraag hoe je met angst in het donker omgaat. Ze vertelt over de ster die haar vader haar gaf om aan te denken wanneer ze bang is. Het prentenboek verbindt het plezier van doen alsof met eenvoudige manieren om elkaar gerust te stellen, zonder van een spannende nacht meteen een gevaarlijke gebeurtenis te maken.","work_id":987109010,"evidence":[{"note":"UlrichKarger picturebook GeisterstundeimKindergarten2002, UliWaas illustration. Reuse exact current edition despite duplicate source keys; no added author or Work.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p241155983"],"reference":"work:6185","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL14933747W","https://data.bibliotheken.nl/id/nbt/p241155983"]},{"type":"cover_front_review","sha256":"f6c6530446b3068b45f3a31a3904e00fcf5efc05ecc16dbdcb97560d3a435d31","cover_id":6387869,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Ulf Blanck/Karole von Wais; Spoken in de speelzaal; De Vier Windstreken. Multiple roles require exact bibliographic review. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL14933747W","reviewed_at":"2026-11-02T19:34:00+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-010","review_status":"approved","bound_author_id":987309008},"before_row":null},{"key":{"edition_id":987209012},"seq":20,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":987109010,"evidence":[{"note":"UlrichKarger picturebook GeisterstundeimKindergarten2002, UliWaas illustration. Reuse exact current edition despite duplicate source keys; no added author or Work.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p241155983"],"reference":"work:6185","checked_at":"2026-11-02T19:34:00.000Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL14933747W","https://data.bibliotheken.nl/id/nbt/p241155983"]},{"type":"cover_front_review","sha256":"f6c6530446b3068b45f3a31a3904e00fcf5efc05ecc16dbdcb97560d3a435d31","cover_id":6387869,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Ulf Blanck/Karole von Wais; Spoken in de speelzaal; De Vier Windstreken. Multiple roles require exact bibliographic review. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6387869-L.jpg?default=false","edition_id":987209012,"bound_title":"Spoken in de speelzaal","reviewed_at":"2026-11-02T19:34:00+00:00","bound_isbn13":"9789055796847","evidence_url":"https://data.bibliotheken.nl/i